; ---- Subroutine: p8b_txt.p8s_chrout ----
    ALIGN 2

p8b_txt.p8s_chrout:
            move.l  sys.DOSBase,a6
            move.b  d0,-(sp)          ; push character, A7 now points to it
            move.l  sp,d1
            moveq   #1,d2
            jsr     -942(a6)          ; WriteChars
            addq.l  #2, sp
            rts
; End of subroutine: p8b_txt.p8s_chrout

